import {
  Box,
  Button,
  Flex,
  Grid,
  Heading,
  Input,
  Text,
  Textarea,
} from "@chakra-ui/react";
import { useQueryClient } from "@tanstack/react-query";
import { useCallback, useEffect, useState } from "react";
import { Link, useAppNavigate, useAppParams } from "../../routing/navigation";
import { getProduct, createProduct, updateProduct } from "../../api/products";
import { serverMessageOr } from "../../api/problem";
import { CategoryTreePicker } from "../../components/shared/CategoryTreePicker";
import { CATEGORIES_KEY } from "../../hooks/useCategories";
import { PhotoPlaceholder } from "../../components/shared/Icons";
import { isValidImageUrl } from "../../utils/url";
import { PrimaryButton } from "../../components/shared/PrimaryButton";

const labelStyle: React.CSSProperties = {
  fontSize: "14px",
  fontWeight: 600,
  color: "#334155",
  display: "block",
  marginBottom: "6px",
};

const CATEGORY_LABEL_ID = "product-category-label";
const CATEGORY_ERROR_ID = "product-category-error";

export function ProductFormPage() {
  const { id } = useAppParams<{ id: string }>();
  const navigate = useAppNavigate();
  const queryClient = useQueryClient();
  const isEdit = Boolean(id);

  const [name, setName] = useState("");
  const [sku, setSku] = useState("");
  const [categoryId, setCategoryId] = useState<string>("");
  const [description, setDescription] = useState("");
  const [photoUrl, setPhotoUrl] = useState("");
  const [loading, setLoading] = useState(false);
  const [loadingData, setLoadingData] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [categoryMissing, setCategoryMissing] = useState(false);

  const loadData = useCallback(async () => {
    setLoadingData(true);
    try {
      if (id) {
        const product = await getProduct(id);
        setName(product.name);
        setSku(product.sku);
        setCategoryId(product.category_id);
        setDescription(product.description ?? "");
        setPhotoUrl(product.photo_url ?? "");
      }
    } catch {
      setError("Failed to load data.");
    } finally {
      setLoadingData(false);
    }
  }, [id]);

  useEffect(() => {
    void loadData();
  }, [loadData]);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!categoryId) {
      setCategoryMissing(true);
      return;
    }
    setLoading(true);
    setError(null);
    const payload = {
      name,
      sku,
      category_id: categoryId,
      description: description || undefined,
      photo_url: photoUrl || undefined,
    };
    try {
      if (isEdit && id) {
        await updateProduct(id, payload);
      } else {
        await createProduct(payload);
      }
      // A product write changes `product_count`, which the cached category tree shows.
      await queryClient.invalidateQueries({ queryKey: CATEGORIES_KEY });
      navigate("/admin/products");
    } catch (err) {
      setError(serverMessageOr(err, "Failed to save product."));
    } finally {
      setLoading(false);
    }
  }

  if (loadingData) {
    return <Text>Loading...</Text>;
  }

  return (
    <Box maxW="800px">
      <Box mb="24px">
        <Flex as="nav" fontSize="13px" color="#64748B" gap="4px" aria-label="Breadcrumb">
          <Link to="/admin/products" style={{ color: "var(--chakra-colors-brand-600)", textDecoration: "none" }}>
            Products
          </Link>
          <Text as="span">/</Text>
          <Text as="span">{isEdit ? "Edit Product" : "Add New Product"}</Text>
        </Flex>
        <Heading as="h1" fontSize="24px" fontWeight="700" color="#0F172A" mt="4px">
          {isEdit ? "Edit Product" : "Add New Product"}
        </Heading>
      </Box>

      <Box as="form" onSubmit={handleSubmit} bg="white" border="1px solid" borderColor="#E2E8F0" borderRadius="12px" p="32px">
        <Grid templateColumns={{ base: "1fr", md: "1fr 1fr" }} gap="20px">
          <Box>
            <label htmlFor="product-name" style={labelStyle}>
              Product Name <Text as="span" color="#EF4444">*</Text>
            </label>
            <Input
              id="product-name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Wireless Headphones Pro"
              required
            />
          </Box>

          <Box>
            <label htmlFor="product-sku" style={labelStyle}>
              SKU <Text as="span" color="#EF4444">*</Text>
            </label>
            <Input
              id="product-sku"
              value={sku}
              onChange={(e) => setSku(e.target.value)}
              placeholder="e.g. WHP-001"
              required
            />
            <Text fontSize="12px" color="#94A3B8" mt="6px">
              Unique stock keeping unit identifier
            </Text>
          </Box>

          <Box>
            <span id={CATEGORY_LABEL_ID} style={labelStyle}>
              Category <Text as="span" color="#EF4444">*</Text>
            </span>
            <CategoryTreePicker
              labelledBy={CATEGORY_LABEL_ID}
              value={categoryId}
              onChange={(next) => {
                setCategoryId(next ?? "");
                setCategoryMissing(false);
              }}
              placeholder="Select a category..."
              aria-invalid={categoryMissing}
              aria-describedby={categoryMissing ? CATEGORY_ERROR_ID : undefined}
            />
            {categoryMissing && (
              <Text id={CATEGORY_ERROR_ID} role="alert" fontSize="12px" color="#DC2626" mt="6px">
                Select a category.
              </Text>
            )}
          </Box>

          <Box gridColumn={{ base: "1", md: "1 / -1" }}>
            <label htmlFor="product-description" style={labelStyle}>
              Description
            </label>
            <Textarea
              id="product-description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Describe your product..."
              rows={4}
            />
          </Box>

          <Box gridColumn={{ base: "1", md: "1 / -1" }}>
            <label htmlFor="product-photo-url" style={labelStyle}>
              Photo URL
            </label>
            <Input
              id="product-photo-url"
              type="url"
              value={photoUrl}
              onChange={(e) => setPhotoUrl(e.target.value)}
              placeholder="https://example.com/image.jpg"
            />
            <Text fontSize="12px" color="#94A3B8" mt="6px">
              External URL to product image
            </Text>
            <Box mt="8px">
              {isValidImageUrl(photoUrl) ? (
                <Box
                  w="120px"
                  h="120px"
                  borderRadius="12px"
                  overflow="hidden"
                  border="1px solid"
                  borderColor="#E2E8F0"
                >
                  <img src={photoUrl} alt="Preview" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                </Box>
              ) : (
                <Flex
                  w="120px"
                  h="120px"
                  border="2px dashed"
                  borderColor="#E2E8F0"
                  borderRadius="12px"
                  align="center"
                  justify="center"
                  direction="column"
                  gap="8px"
                  color="#94A3B8"
                  fontSize="11px"
                  textAlign="center"
                  p="8px"
                >
                  <PhotoPlaceholder size={32} />
                  <span>Image preview</span>
                </Flex>
              )}
            </Box>
          </Box>
        </Grid>

        {error && (
          <Box role="alert" mt="16px" p="12px" bg="#FEE2E2" borderRadius="8px" fontSize="13px" color="#991B1B">
            {error}
          </Box>
        )}

        <Flex justify="flex-end" gap="12px" mt="28px" pt="20px" borderTop="1px solid" borderColor="#F1F5F9">
          <Button asChild variant="outline">
            <Link to="/admin/products">Cancel</Link>
          </Button>
          <PrimaryButton type="submit" loading={loading}>
            Save Product
          </PrimaryButton>
        </Flex>
      </Box>
    </Box>
  );
}

import { useRef, type KeyboardEvent, type ReactNode } from "react";
import { nextIndex } from "../../components/shared/rovingIndex";

/** One layout card. A `locked` layout is shown but cannot be chosen. */
export interface LayoutOption {
  key: string;
  label: string;
  description: string;
  thumbnail: { src: string; alt: string };
  recommended?: boolean;
  locked?: boolean;
}

interface LayoutTabProps {
  value: string;
  options: LayoutOption[];
  onSelect: (key: string) => void;
  /** Why the locked layouts are locked, shown above them, with an id the
   * locked cards point to. */
  lockedNote?: ReactNode;
}

const LOCKED_NOTE_ID = "editor-layout-locked-note";

/** The layout cards, as a radio group in `options` order. Locked cards are
 * `aria-disabled` and skipped by the arrow keys. */
export function LayoutTab({ value, options, onSelect, lockedNote }: LayoutTabProps) {
  const cardRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const selectable = options.filter((option) => !option.locked);

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, key: string) {
    const index = selectable.findIndex((option) => option.key === key);
    const next = nextIndex(event.key, index, selectable.length);
    if (next === null) return;
    event.preventDefault();
    const target = selectable[next];
    onSelect(target.key);
    cardRefs.current[options.indexOf(target)]?.focus();
  }

  return (
    <div className="flex flex-col gap-2.5">
      {lockedNote && options.some((option) => option.locked) && (
        <div id={LOCKED_NOTE_ID} className="rounded-2xl bg-accent-soft p-3 text-[12.5px] text-ink">
          {lockedNote}
        </div>
      )}
      <div role="radiogroup" aria-label="Układ strony" className="grid grid-cols-2 gap-2.5">
        {options.map((layout, index) => {
          const selected = layout.key === value;
          const labelId = `editor-layout-${layout.key}-label`;
          const badgeId = `editor-layout-${layout.key}-badge`;
          const descriptionId = `editor-layout-${layout.key}-description`;
          const describedBy = [
            layout.recommended ? badgeId : null,
            descriptionId,
            layout.locked && lockedNote ? LOCKED_NOTE_ID : null,
          ]
            .filter(Boolean)
            .join(" ");
          return (
            <button
              key={layout.key}
              ref={(element) => {
                cardRefs.current[index] = element;
              }}
              type="button"
              role="radio"
              aria-checked={selected}
              aria-disabled={layout.locked || undefined}
              aria-labelledby={labelId}
              aria-describedby={describedBy}
              tabIndex={selected ? 0 : -1}
              onClick={() => {
                if (!layout.locked) onSelect(layout.key);
              }}
              onKeyDown={(event) => handleKeyDown(event, layout.key)}
              className={`relative flex min-h-[44px] flex-col gap-1.5 rounded-2xl border-2 p-2.5 text-left font-sans focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring ${
                selected ? "border-primary bg-primary-soft" : "border-line bg-paper"
              } ${layout.locked ? "cursor-not-allowed" : ""}`}
            >
              <img
                src={layout.thumbnail.src}
                alt={layout.thumbnail.alt}
                className={`w-full rounded-xl ${layout.locked ? "opacity-50 grayscale" : ""}`}
              />
              <span id={labelId} className="text-sm font-bold text-ink">
                {layout.label}
              </span>
              {layout.recommended && (
                <span
                  id={badgeId}
                  className="self-start rounded-full bg-accent-soft px-2 py-0.5 text-[11px] font-extrabold text-accent-fg"
                >
                  Polecany
                </span>
              )}
              {layout.locked && (
                <span className="self-start rounded-full bg-cream px-2 py-0.5 text-[11px] font-extrabold text-ink-soft">
                  <span aria-hidden="true">🔒 </span>
                  Dla organizacji
                </span>
              )}
              <span id={descriptionId} className="text-[12px] text-ink-soft">
                {layout.description}
              </span>
              {selected && (
                <span
                  aria-hidden="true"
                  className="absolute right-2 top-2 flex h-6 w-6 items-center justify-center rounded-full bg-primary text-xs font-extrabold text-on-primary"
                >
                  ✓
                </span>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}

